def _build_type(type_, value, property_path=None):
    """ Builds the schema definition based on the given type for the given value.

    :param type_: The type of the value
    :param value: The value to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]
    """
    if type_ in ('boolean', 'integer', 'number', 'string'):
        return {
            'type': type_,
            'format': 'date' if type_ == 'string' else None,
            'pattern': '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' if type_ == 'string' else None,
        }
    if type_ == 'array':
        return {
            'type': 'array',
            'items': _build_type(value[0], value[1:], property_path=property_path)
        }
    if type_ == 'object':
        return {
            'type': 'object',
            'properties': {
                key: _build_type(value_type, value_type, property_path=property_path + [key])
                for key, value_type in value.items()
            },
            'required': [key for key, value_type in value.items() if value_type != '?']
        }

    raise ValueError(f'Unsupported type {type_}')

