def build(schema):
    """ Builds a schema based on the given schema definition.

    :param Dict[str, Any] schema: The schema definition
    :return: The built schema
    :rtype: Dict[str, Any]
    """
    return {
        'type': 'object',
        'properties': {
            key: _build_type(type_, value, property_path=[key])
            for key, (type_, value) in schema.items()
        },
        'required': [key for key, (type_, value) in schema.items() if type_ != '?'],
    }


